import type React from 'react';
import { useEffect, useRef } from 'react';

interface CodeStreamDisplayProps {
  code: string;
  isStreaming: boolean;
  maxVisibleLines?: number;
  onComplete?: () => void;
}

export const CodeStreamDisplay: React.FC<CodeStreamDisplayProps> = ({
  code,
  isStreaming,
  maxVisibleLines = 3,
  onComplete,
}) => {
  const codeDisplayRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom when streaming or code changes
  // biome-ignore lint/correctness/useExhaustiveDependencies: 需要在代码变化时滚动
  useEffect(() => {
    if (codeDisplayRef.current) {
      // 始终滚动到底部，不管是否在流式传输
      codeDisplayRef.current.scrollTop = codeDisplayRef.current.scrollHeight;
    }
  }, [code]); // 监听 code 变化而不是 isStreaming

  // 完成回调
  useEffect(() => {
    if (!isStreaming && onComplete && code) {
      onComplete();
    }
  }, [isStreaming, code, onComplete]);

  // 计算可见行数的高度
  const maxHeight = maxVisibleLines * 1.5; // em

  return (
    <div className="relative overflow-hidden rounded-lg bg-gray-900">
      <div
        className="w-full select-none whitespace-pre bg-gray-900 p-4 font-mono text-gray-100 text-sm"
        ref={codeDisplayRef}
        style={{
          maxHeight: `${maxHeight}em`,
          overflowY: 'auto',
          overflowX: 'auto',
          // Hide scrollbar
          scrollbarWidth: 'none' as any,
          msOverflowStyle: 'none',
          WebkitUserSelect: 'none',
          MozUserSelect: 'none',
          userSelect: 'none',
        }}
      >
        {code}
      </div>
      <style>{`
        .select-none::-webkit-scrollbar {
          display: none;
        }
      `}</style>
      {isStreaming && code && (
        <div className="pointer-events-none absolute right-0 bottom-0 left-0 h-8 bg-gradient-to-t from-gray-900 to-transparent" />
      )}
    </div>
  );
};
