// Get a random mock HTML string
export function getRandomMockHtml(): string {
  return mockHtmlStrings[Math.floor(Math.random() * mockHtmlStrings.length)];
}

// Create an infinite cycling iterator for mock HTML
export function* mockHtmlIterator(): Generator<string, void, unknown> {
  let index = 0;
  while (true) {
    yield mockHtmlStrings[index % mockHtmlStrings.length];
    index++;
  }
}
