import type { UnifiedModel } from '@/lib/ai-config-provider';

const STORAGE_PREFIX = 'zeroy_ai_selected_model_';

export const createModelStorageKey = (baseUrl: string) =>
  `${STORAGE_PREFIX}${btoa(baseUrl)
    .replace(/[^a-zA-Z0-9]/g, '')
    .substring(0, 10)}`;

export const findFirstValidModel = (
  models: UnifiedModel[],
  candidates: Array<string | undefined | null>
): string | null => {
  if (!models.length) {
    return null;
  }
  const ids = new Set(models.map((model) => model.id));
  for (const candidate of candidates) {
    if (candidate && ids.has(candidate)) {
      return candidate;
    }
  }
  return null;
};

// 判断字符串中是否存在一个"4"字符，且其前后都不是数字
const hasBoundedDigit4 = (text: string): boolean => {
  for (let i = 0; i < text.length; i++) {
    if (text[i] !== '4') {
      continue;
    }
    const prev = i > 0 ? text[i - 1] : '';
    const next = i < text.length - 1 ? text[i + 1] : '';
    const isPrevDigit = prev >= '0' && prev <= '9';
    const isNextDigit = next >= '0' && next <= '9';
    if (isPrevDigit) {
      continue;
    }
    if (isNextDigit) {
      continue;
    }
    return true;
  }
  return false;
};

export const findPreferredModel = (models: UnifiedModel[]): string | null => {
  if (!models.length) {
    return null;
  }

  // 优先查找包含 "sonnet" 和 "4" 的模型
  const sonnet4Model = models.find((model) => {
    const modelIdLower = model.id.toLowerCase();
    const modelNameLower = model.name.toLowerCase();
    const idMatches =
      modelIdLower.includes('sonnet') && hasBoundedDigit4(modelIdLower);
    const nameMatches =
      modelNameLower.includes('sonnet') && hasBoundedDigit4(modelNameLower);
    return idMatches || nameMatches;
  });

  if (sonnet4Model) {
    return sonnet4Model.id;
  }

  // 如果没找到，回退到第一个模型
  return models[0].id;
};

export const persistModelSelection = (
  storageKey: string | null,
  modelId: string | null
) => {
  if (!storageKey) {
    return;
  }
  if (modelId) {
    localStorage.setItem(storageKey, modelId);
  } else {
    localStorage.removeItem(storageKey);
  }
};

export interface InitialModelOptions {
  saved?: string | null;
  defaultModel?: string | null;
  currentSelection?: string;
}

export const chooseInitialModel = (
  models: UnifiedModel[],
  options: InitialModelOptions
): string | null => {
  const preferred = findFirstValidModel(models, [
    options.saved,
    options.defaultModel,
    options.currentSelection,
  ]);
  if (preferred) {
    return preferred;
  }
  // 如果没有首选项，使用智能选择逻辑（优先选择 sonnet 4）
  return findPreferredModel(models);
};

export const ensureSelectionExists = (
  models: UnifiedModel[],
  currentSelection?: string | null
): string | null => {
  if (!models.length) {
    return null;
  }
  if (
    currentSelection &&
    models.some((model) => model.id === currentSelection)
  ) {
    return currentSelection;
  }
  // 如果当前选择不存在，使用智能选择逻辑
  return findPreferredModel(models);
};

/** 日期后缀正则（如 20250514） */
const DATE_SUFFIX_REGEX = /20\d{6}/;

/** 检查模型 ID/名称是否带日期后缀 */
const hasDateSuffix = (text: string): boolean => DATE_SUFFIX_REGEX.test(text);

/**
 * 常用模型匹配规则
 * 基础匹配 + 是否优先带日期版本
 */
const POPULAR_MODEL_PATTERNS: Array<{
  match: (id: string, name: string) => boolean;
  priority: number;
  unique: string;
  preferDate: boolean; // 是否优先选带日期的版本
}> = [
  // Claude Sonnet 4.5
  {
    match: (id, name) => {
      const text = `${id} ${name}`.toLowerCase();
      return (
        text.includes('sonnet') &&
        (text.includes('4.5') || text.includes('4-5'))
      );
    },
    priority: 100,
    unique: 'sonnet-4.5',
    preferDate: true,
  },
  // Claude Sonnet 4.0
  {
    match: (id, name) => {
      const text = `${id} ${name}`.toLowerCase();
      const isSonnet4 =
        text.includes('sonnet') &&
        (text.includes('4.0') ||
          text.includes('4-0') ||
          hasBoundedDigit4(text));
      const is45 = text.includes('4.5') || text.includes('4-5');
      return isSonnet4 && !is45;
    },
    priority: 90,
    unique: 'sonnet-4.0',
    preferDate: true,
  },
  // Gemini 3 Pro Preview（精确匹配 gemini-3-pro-preview）
  {
    match: (id, name) => {
      const text = `${id} ${name}`.toLowerCase();
      return (
        (text.includes('gemini-3') || text.includes('gemini3')) &&
        text.includes('pro') &&
        text.includes('preview') &&
        !text.includes('image') &&
        !text.includes('search')
      );
    },
    priority: 80,
    unique: 'gemini-3-pro',
    preferDate: false,
  },
];

/** 最小模型接口，只需要 id 和 name */
interface MinimalModel {
  id: string;
  name: string;
}

/** 从候选列表中选出最佳模型（优先带日期的） */
const selectBestModel = <T extends MinimalModel>(
  candidates: Array<{ model: T; preferDate: boolean }>
): T => {
  const { preferDate } = candidates[0];
  if (!preferDate || candidates.length === 1) {
    return candidates[0].model;
  }
  const withDate = candidates.find((c) =>
    hasDateSuffix(`${c.model.id} ${c.model.name}`)
  );
  return withDate ? withDate.model : candidates[0].model;
};

/**
 * 从模型列表中筛选出常用模型
 * @param models 完整模型列表
 * @param maxCount 最大返回数量，默认 5
 * @returns 按优先级排序的常用模型列表
 */
export const filterPopularModels = <T extends MinimalModel>(
  models: T[],
  maxCount = 5
): T[] => {
  type Candidate = { model: T; priority: number; preferDate: boolean };
  const candidatesByUnique = new Map<string, Candidate[]>();

  // 收集每个 unique key 的匹配模型
  for (const model of models) {
    for (const pattern of POPULAR_MODEL_PATTERNS) {
      if (!pattern.match(model.id, model.name)) {
        continue;
      }
      const list = candidatesByUnique.get(pattern.unique) ?? [];
      list.push({
        model,
        priority: pattern.priority,
        preferDate: pattern.preferDate,
      });
      candidatesByUnique.set(pattern.unique, list);
      break;
    }
  }

  // 从每个 unique key 选出最佳模型
  const result: Array<{ model: T; priority: number }> = [];
  for (const candidates of candidatesByUnique.values()) {
    if (candidates.length === 0) {
      continue;
    }
    result.push({
      model: selectBestModel(candidates),
      priority: candidates[0].priority,
    });
  }

  return result
    .sort((a, b) => b.priority - a.priority)
    .slice(0, maxCount)
    .map((item) => item.model);
};
