import type React from 'react';
import { useEffect, useMemo, useRef, useState } from 'react';
import { filterPopularModels } from '@/lib/model-selection';

interface Model {
  id: string;
  name: string;
  created?: number;
  owned_by?: string;
}

interface ModelSelectProps {
  models: Model[];
  value: string;
  onChange: (value: string) => void;
  isLoading?: boolean;
  placeholder?: string;
  className?: string;
}

export const ModelSelect: React.FC<ModelSelectProps> = ({
  models,
  value,
  onChange,
  isLoading = false,
  placeholder = '请选择模型',
  className,
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [highlightedIndex, setHighlightedIndex] = useState(0);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);

  // 过滤和分组模型
  const { filteredModels, groupedModels } = useMemo(() => {
    const query = searchQuery.toLowerCase();
    const filtered = models.filter(
      (model) =>
        model.id.toLowerCase().includes(query) ||
        model.name.toLowerCase().includes(query)
    );

    // 按 owned_by 分组
    const grouped = filtered.reduce(
      (acc, model) => {
        const owner = model.owned_by || 'other';
        if (!acc[owner]) {
          acc[owner] = [];
        }
        acc[owner].push(model);
        return acc;
      },
      {} as Record<string, Model[]>
    );

    return { filteredModels: filtered, groupedModels: grouped };
  }, [models, searchQuery]);

  // 智能筛选常用模型
  const popularModels = useMemo(() => filterPopularModels(models, 5), [models]);

  // 获取选中的模型
  const selectedModel = models.find((m) => m.id === value);

  // 点击外部关闭下拉框
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        dropdownRef.current &&
        !dropdownRef.current.contains(event.target as Node)
      ) {
        setIsOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // 打开下拉框时聚焦搜索框
  useEffect(() => {
    if (isOpen && searchInputRef.current) {
      searchInputRef.current.focus();
    }
  }, [isOpen]);

  // 键盘导航
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (!isOpen) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        setIsOpen(true);
      }
      return;
    }

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setHighlightedIndex((prev) =>
          prev < filteredModels.length - 1 ? prev + 1 : prev
        );
        break;
      case 'ArrowUp':
        e.preventDefault();
        setHighlightedIndex((prev) => (prev > 0 ? prev - 1 : 0));
        break;
      case 'Enter':
        e.preventDefault();
        if (filteredModels[highlightedIndex]) {
          onChange(filteredModels[highlightedIndex].id);
          setIsOpen(false);
          setSearchQuery('');
        }
        break;
      case 'Escape':
        e.preventDefault();
        setIsOpen(false);
        setSearchQuery('');
        break;
      default:
        // Allow other keys to work normally
        break;
    }
  };

  const handleModelSelect = (modelId: string) => {
    onChange(modelId);
    setIsOpen(false);
    setSearchQuery('');
  };

  // 获取模型提供商的显示名称
  const getOwnerDisplayName = (owner: string) => {
    const ownerMap: Record<string, string> = {
      OpenAI: 'OpenAI',
      custom: '自定义模型',
      Anthropic: 'Anthropic',
      Google: 'Google',
      Meta: 'Meta',
      other: '其他',
    };
    return ownerMap[owner] || owner;
  };

  // 获取模型提供商的图标颜色
  const getOwnerColor = (owner: string) => {
    const colorMap: Record<string, string> = {
      OpenAI: 'text-green-600',
      custom: 'text-blue-600',
      Anthropic: 'text-purple-600',
      Google: 'text-red-600',
      Meta: 'text-indigo-600',
      other: 'text-gray-600',
    };
    return colorMap[owner] || 'text-gray-600';
  };

  if (isLoading) {
    return (
      <div className="w-full rounded-lg border border-gray-300 bg-gray-50 px-4 py-3 text-sm">
        <span className="text-gray-500">正在加载模型列表...</span>
      </div>
    );
  }

  return (
    <div className={`relative ${className ?? ''}`} ref={dropdownRef}>
      <button
        aria-expanded={isOpen}
        aria-haspopup="listbox"
        className="flex w-full items-center justify-between rounded-lg border border-gray-300 bg-white px-4 py-3 text-left text-sm transition-colors hover:border-gray-400 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-500/20"
        onClick={() => setIsOpen(!isOpen)}
        onKeyDown={handleKeyDown}
        type="button"
      >
        <span className={selectedModel ? 'text-gray-900' : 'text-gray-500'}>
          {selectedModel ? selectedModel.name : placeholder}
        </span>
        <svg
          className={`ml-2 h-5 w-5 text-gray-400 transition-transform ${
            isOpen ? 'rotate-180' : ''
          }`}
          fill="currentColor"
          viewBox="0 0 20 20"
          xmlns="http://www.w3.org/2000/svg"
        >
          <title>Dropdown arrow</title>
          <path
            clipRule="evenodd"
            d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"
            fillRule="evenodd"
          />
        </svg>
      </button>

      {isOpen && (
        <div className="absolute z-50 mt-2 w-full rounded-lg border border-gray-200 bg-white shadow-lg">
          {/* 搜索框 */}
          <div className="border-gray-200 border-b p-3">
            <input
              className="w-full rounded-md border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-500/20"
              onChange={(e) => {
                setSearchQuery(e.target.value);
                setHighlightedIndex(0);
              }}
              onKeyDown={handleKeyDown}
              placeholder="搜索模型..."
              ref={searchInputRef}
              type="text"
              value={searchQuery}
            />
            <div className="mt-2 text-gray-500 text-xs">
              找到 {filteredModels.length} 个模型
            </div>
          </div>

          {/* 模型列表 */}
          <div
            className="max-h-80 overflow-y-auto"
            style={{ scrollBehavior: 'smooth' }}
          >
            {filteredModels.length === 0 ? (
              <div className="px-4 py-8 text-center text-gray-500 text-sm">
                没有找到匹配的模型
              </div>
            ) : (
              <div className="py-2">
                {Object.entries(groupedModels).map(([owner, modelList]) => (
                  <div key={owner}>
                    <div className="flex items-center px-3 py-2">
                      <span
                        className={`font-medium text-xs ${getOwnerColor(owner)}`}
                      >
                        {getOwnerDisplayName(owner)}
                      </span>
                      <span className="ml-2 text-gray-400 text-xs">
                        ({modelList.length})
                      </span>
                    </div>
                    {modelList.map((model, _index) => {
                      const globalIndex = filteredModels.findIndex(
                        (m) => m.id === model.id
                      );
                      const isHighlighted = highlightedIndex === globalIndex;
                      const isSelected = value === model.id;

                      return (
                        <button
                          className={`flex w-full items-center px-4 py-2 text-left text-sm transition-colors ${(() => {
                            if (isHighlighted) {
                              return 'bg-blue-50 text-blue-900';
                            }
                            if (isSelected) {
                              return 'bg-gray-50 text-gray-900';
                            }
                            return 'text-gray-700 hover:bg-gray-50';
                          })()}`}
                          key={model.id}
                          onClick={() => handleModelSelect(model.id)}
                          type="button"
                        >
                          <span className="flex-1">{model.name}</span>
                          {isSelected && (
                            <svg
                              className="ml-2 h-4 w-4 text-blue-600"
                              fill="currentColor"
                              viewBox="0 0 20 20"
                              xmlns="http://www.w3.org/2000/svg"
                            >
                              <title>Selected</title>
                              <path
                                clipRule="evenodd"
                                d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"
                                fillRule="evenodd"
                              />
                            </svg>
                          )}
                        </button>
                      );
                    })}
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* 常用模型快捷选择 */}
          {popularModels.length > 0 && (
            <div className="border-gray-200 border-t p-3">
              <div className="mb-2 font-medium text-gray-600 text-xs">
                常用模型
              </div>
              <div className="flex flex-wrap gap-2">
                {popularModels.map((model) => (
                  <button
                    className="rounded-md bg-gray-100 px-3 py-1 font-medium text-gray-700 text-xs hover:bg-gray-200"
                    key={model.id}
                    onClick={() => handleModelSelect(model.id)}
                    type="button"
                  >
                    {model.name}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};
