import { useEffect, useMemo, useState } from 'react';
import {
  fetchModelListWithFallback,
  type ModelListResult,
} from '@/lib/ai-config-provider';
import {
  type AiSettingsLike,
  extractAiCredentials,
} from '@/lib/ai-credentials';

interface UseAIModelAvailabilityOptions {
  enabled?: boolean;
  forceRefresh?: boolean;
  credentials?: AiSettingsLike | null;
}

export interface UseAIModelAvailabilityResult {
  loading: boolean;
  available: boolean;
  source: ModelListResult['source'];
  error?: string;
  result?: ModelListResult;
}

const hasModelsOrSuggestions = (result: ModelListResult): boolean => {
  if (!result) {
    return false;
  }
  if (Array.isArray(result.models) && result.models.length > 0) {
    return true;
  }
  if (Array.isArray(result.suggestions) && result.suggestions.length > 0) {
    return true;
  }
  return false;
};

export function useAIModelAvailability(
  options: UseAIModelAvailabilityOptions = {}
): UseAIModelAvailabilityResult {
  const {
    enabled = true,
    forceRefresh = false,
    credentials: override,
  } = options;

  const resolvedSource = override ?? window.zeroyEditor?.aiSettings ?? null;

  const credentials = useMemo(
    () => extractAiCredentials(resolvedSource),
    [resolvedSource]
  );

  const [state, setState] = useState<UseAIModelAvailabilityResult>({
    loading: false,
    available: credentials.hasCredentials,
    source: 'none',
    result: undefined,
    error: undefined,
  });

  useEffect(() => {
    setState((prev) => ({
      ...prev,
      available: credentials.hasCredentials,
      source: credentials.hasCredentials ? prev.source : 'none',
      result: credentials.hasCredentials ? prev.result : undefined,
      error: credentials.hasCredentials ? prev.error : undefined,
    }));
  }, [credentials.hasCredentials]);

  useEffect(() => {
    if (!enabled) {
      setState({
        loading: false,
        available: false,
        source: 'none',
        result: undefined,
        error: undefined,
      });
      return;
    }

    if (!credentials.hasCredentials) {
      setState({
        loading: false,
        available: false,
        source: 'none',
        result: undefined,
        error: undefined,
      });
      return;
    }

    let cancelled = false;
    const controller = new AbortController();

    setState((prev) => ({
      ...prev,
      loading: true,
      available: true,
      error: undefined,
    }));

    fetchModelListWithFallback({
      apiToken: credentials.apiToken || undefined,
      baseUrl: credentials.baseUrl || undefined,
      apiKey: credentials.apiKey || undefined,
      forceRefresh,
      signal: controller.signal,
    })
      .then((result) => {
        if (cancelled) {
          return;
        }
        const available = hasModelsOrSuggestions(result);
        setState({
          loading: false,
          available,
          source: result.source,
          error: available
            ? undefined
            : result.serverErrorMessage ||
              result.localErrorMessage ||
              '无法获取模型列表，请检查配置',
          result,
        });
      })
      .catch((error) => {
        if (cancelled) {
          return;
        }
        setState({
          loading: false,
          available: false,
          source: 'none',
          error: error instanceof Error ? error.message : String(error ?? ''),
        });
      });

    return () => {
      cancelled = true;
      controller.abort();
    };
  }, [
    credentials.apiKey,
    credentials.apiToken,
    credentials.baseUrl,
    credentials.hasCredentials,
    enabled,
    forceRefresh,
  ]);

  return state;
}
