import type React from 'react';
import { useCallback, useState } from 'react';
import { useNotification } from '@/components/notification';
import { extractCodeFromMarkdown } from '@/lib/extract-code-from-markdown';

interface CodeDisplayProps {
  code: string;
  maxLines?: number;
  onInsert?: (code: string) => void;
  showInsertButton?: boolean;
}

export const CodeDisplay: React.FC<CodeDisplayProps> = ({
  code,
  maxLines = 10,
  onInsert,
  showInsertButton = false,
}) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const { notify } = useNotification();

  // 提取实际的代码内容（去除 Markdown 包裹）
  const actualCode = extractCodeFromMarkdown(code);

  // 计算代码行数
  const lines = actualCode.split('\n');
  const lineCount = lines.length;
  const shouldShowToggle = lineCount > maxLines;

  // 获取要显示的代码
  const displayCode =
    isExpanded || !shouldShowToggle
      ? actualCode
      : lines.slice(0, maxLines).join('\n') + (shouldShowToggle ? '\n...' : '');

  // 复制代码
  const handleCopy = useCallback(() => {
    // 检查是否支持 Clipboard API
    if (navigator.clipboard?.writeText) {
      navigator.clipboard
        .writeText(actualCode)
        .then(() => {
          notify('success', '代码已复制到剪贴板');
        })
        .catch(() => {
          notify('error', '复制失败');
        });
    } else {
      // 降级方案：使用传统的复制方法
      const textArea = document.createElement('textarea');
      textArea.value = actualCode;
      textArea.style.position = 'fixed';
      textArea.style.left = '-999999px';
      textArea.style.top = '-999999px';
      document.body.appendChild(textArea);
      textArea.focus();
      textArea.select();

      try {
        const successful = document.execCommand('copy');
        if (successful) {
          notify('success', '代码已复制到剪贴板');
        } else {
          notify('error', '复制失败');
        }
      } catch (_err) {
        notify('error', '复制失败');
      }

      document.body.removeChild(textArea);
    }
  }, [actualCode, notify]);

  // 插入代码
  const handleInsert = useCallback(() => {
    if (onInsert) {
      onInsert(actualCode);
    }
  }, [actualCode, onInsert]);

  return (
    <div className="group relative">
      {/* 代码预览 */}
      <div className="overflow-hidden rounded-lg bg-gray-900">
        <div
          className="w-full select-none overflow-auto whitespace-pre bg-gray-900 p-4 font-mono text-gray-100 text-sm"
          style={{
            height: isExpanded ? 'auto' : `${maxLines * 1.5}em`,
            minHeight: `${maxLines * 1.5}em`,
            userSelect: 'none',
            WebkitUserSelect: 'none',
            MozUserSelect: 'none',
            msUserSelect: 'none',
          }}
        >
          {displayCode}
        </div>
      </div>

      {/* 工具栏 - 悬停时显示 */}
      <div className="absolute top-2 right-2 flex gap-2 opacity-0 transition-opacity group-hover:opacity-100">
        {/* 复制按钮 */}
        <button
          className="rounded bg-gray-800 px-3 py-1 text-gray-300 text-xs transition-colors hover:bg-gray-700 hover:text-white"
          onClick={handleCopy}
          type="button"
        >
          复制
        </button>

        {/* 展开/收起按钮 */}
        {shouldShowToggle && (
          <button
            className="rounded bg-gray-800 px-3 py-1 text-gray-300 text-xs transition-colors hover:bg-gray-700 hover:text-white"
            onClick={() => setIsExpanded(!isExpanded)}
            type="button"
          >
            {isExpanded ? '收起' : `展开 (${lineCount} 行)`}
          </button>
        )}
      </div>

      {/* 插入按钮 - 在代码框下方 */}
      {showInsertButton && onInsert && (
        <div className="mt-3">
          <button
            className="w-full rounded-md bg-blue-600 px-4 py-2 font-medium text-white transition-colors hover:bg-blue-700"
            onClick={handleInsert}
            type="button"
          >
            插入到编辑器
          </button>
        </div>
      )}
    </div>
  );
};
