// Define regex patterns at module level for better performance
const CODE_BLOCK_REGEX = /^```(?:\w+)?\s*\n([\s\S]*?)\n```$/m;

/**
 * Extract code content from markdown code blocks
 * Handles both ```html...``` and ```...``` formats
 *
 * @param text - The text that might contain markdown code blocks
 * @returns The extracted code content without markdown wrappers
 */
export function extractCodeFromMarkdown(text: string): string {
  if (!text) {
    return '';
  }

  const match = text.match(CODE_BLOCK_REGEX);

  if (match) {
    // Return the content inside the code block
    return match[1].trim();
  }

  // If no markdown code block found, return the original text
  return text.trim();
}
