import { useEffect, useRef, useState } from 'react';
import { mockHtmlIterator } from '../mock';
import { CodeStreamDisplay } from './code-stream-display';

interface FakeStreamDisplayProps {
  isActive: boolean;
}

export function FakeStreamDisplay({ isActive }: FakeStreamDisplayProps) {
  const [displayedCode, setDisplayedCode] = useState('');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isThinking, setIsThinking] = useState(true);
  const iteratorRef = useRef(mockHtmlIterator());
  const currentHtmlRef = useRef('');
  const intervalRef = useRef<number | null>(null);
  const thinkingTimeoutRef = useRef<number | null>(null);

  useEffect(() => {
    if (!isActive) {
      // Reset when not active
      setDisplayedCode('');
      setCurrentIndex(0);
      setIsThinking(true);
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
      if (thinkingTimeoutRef.current) {
        clearTimeout(thinkingTimeoutRef.current);
        thinkingTimeoutRef.current = null;
      }
      return;
    }

    // Start with thinking phase
    if (isThinking) {
      thinkingTimeoutRef.current = window.setTimeout(() => {
        setIsThinking(false);
      }, 2000); // 2 seconds thinking time
      return;
    }

    // Start fake streaming after thinking
    const streamCharacters = () => {
      // If we've finished the current HTML, get the next one
      if (currentIndex === 0 || currentIndex >= currentHtmlRef.current.length) {
        const { value } = iteratorRef.current.next();
        if (value) {
          currentHtmlRef.current = value;
          setCurrentIndex(0);
          setDisplayedCode(''); // Clear for new HTML
        }
      }

      // Add characters progressively
      if (currentIndex < currentHtmlRef.current.length) {
        const charsToAdd = Math.min(
          5,
          currentHtmlRef.current.length - currentIndex
        ); // Add 1-5 chars at a time
        const newCode = currentHtmlRef.current.substring(
          0,
          currentIndex + charsToAdd
        );
        setDisplayedCode(newCode);
        setCurrentIndex(currentIndex + charsToAdd);
      }
    };

    // Start the interval
    intervalRef.current = window.setInterval(streamCharacters, 50); // Stream every 50ms

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
      if (thinkingTimeoutRef.current) {
        clearTimeout(thinkingTimeoutRef.current);
      }
    };
  }, [isActive, currentIndex, isThinking]);

  if (!isActive) {
    return null;
  }

  return (
    <div className="mb-4 text-left">
      <div className="inline-block w-full max-w-2xl">
        {isThinking ? (
          <div className="flex items-center gap-2">
            <div className="h-4 w-4 animate-spin rounded-full border-2 border-blue-500 border-t-transparent" />
            <p className="text-gray-600 text-sm">🤔 思考中...</p>
          </div>
        ) : (
          <>
            <p className="mb-2 text-gray-600 text-sm">🤖 正在生成代码...</p>
            <CodeStreamDisplay
              code={displayedCode}
              isStreaming={true}
              maxVisibleLines={2}
            />
          </>
        )}
      </div>
    </div>
  );
}
